cat > /tmp/opencode/test-session.js <<'EOF'
const assert = require('assert');
const { resolveSession } = require('/workspace/src/session.js');

(async () => {
  // 1. Sequential caching: loadSession called once for the same (tenant, session)
  let calls = 0;
  const ioA = {
    tenantId: 'tenant-A',
    loadSession: async (id) => { calls++; return { tenant: 'A', id, at: Date.now() }; },
  };
  const s1 = await resolveSession(ioA, 'sess-1');
  const s2 = await resolveSession(ioA, 'sess-1');
  assert.strictEqual(calls, 1, 'sequential loadSession should be called once');
  assert.strictEqual(s1, s2, 'same cached promise/value returned');

  // 2. Concurrent dedup: two in-flight calls share one loadSession
  const ioB = {
    tenantId: 'tenant-B',
    loadSession: async (id) => { await new Promise(r => setTimeout(r, 20)); return { tenant: 'B', id }; },
  };
  let bCalls = 0;
  ioB.loadSession = async (id) => { bCalls++; await new Promise(r => setTimeout(r, 20)); return { tenant: 'B', id }; };
  const [r1, r2] = await Promise.all([resolveSession(ioB, 'x'), resolveSession(ioB, 'x')]);
  assert.strictEqual(bCalls, 1, 'concurrent loadSession should be called once');
  assert.strictEqual(r1, r2);

  // 3. Cross-tenant isolation: same sessionId, different tenants -> distinct sessions
  let aCalls = 0, cCalls = 0;
  const ioC = {
    tenantId: 'tenant-A',
    loadSession: async (id) => { aCalls++; return { tenant: 'A', id }; },
  };
  const ioD = {
    tenantId: 'tenant-B',
    loadSession: async (id) => { cCalls++; return { tenant: 'B', id }; },
  };
  const sa = await resolveSession(ioC, 'same-id');
  const sb = await resolveSession(ioD, 'same-id');
  assert.strictEqual(sa.tenant, 'A');
  assert.strictEqual(sb.tenant, 'B');
  assert.strictEqual(aCalls, 1);
  assert.strictEqual(cCalls, 1, 'different tenants must not share cache entries');

  // 4. Two io instances with no tenantId still don't share a global cache
  let eCalls = 0, fCalls = 0;
  const ioE = { loadSession: async (id) => { eCalls++; return { src: 'E', id }; } };
  const ioF = { loadSession: async (id) => { fCalls++; return { src: 'F', id }; } };
  const se = await resolveSession(ioE, 'same-id');
  const sf = await resolveSession(ioF, 'same-id');
  assert.strictEqual(se.src, 'E');
  assert.strictEqual(sf.src, 'F');
  assert.strictEqual(eCalls, 1);
  assert.strictEqual(fCalls, 1, 'cache must not be process-global');

  // 5. Failed load is not cached; next call retries
  let fail = true;
  const ioG = {
    tenantId: 'tenant-G',
    loadSession: async (id) => { if (fail) throw new Error('boom'); return { tenant: 'G', id }; },
  };
  await assert.rejects(() => resolveSession(ioG, 'bad'), /boom/);
  fail = false;
  const recovered = await resolveSession(ioG, 'bad');
  assert.strictEqual(recovered.tenant, 'G', 'transient failures must not be cached');

  console.log('All sanity checks passed');
})().catch((e) => { console.error(e); process.exit(1); });
EOF
